    #10;
    assert (seg == 7'b1000000)
    else 
      $error("Seven segment display integration failed.", $time); 

      // Counter integration test
    reset = 0;
      #50 reset = 1; 
    #80
    assert (led[2] == 1)
    else 
      $error("Counter integration failed.", $time); 

      #100 $stop;
    end
  endmodule

