After much trial and error, everything worked. the LED blinked and the seven segment display was controllable. I spent about 30-35 hours on this lab.

## AI Prototype Summary

I gave ChatGPT the promtp and it gave me this code:

module led_blink (
    output logic led
);

    // UP5K internal high-frequency oscillator
    logic clk;

    SB_HFOSC #(
        .CLKHF_DIV("0b00")    // 48 MHz
    ) hfosc (
        .CLKHFPU(1'b1),       // Power up oscillator
        .CLKHFEN(1'b1),       // Enable oscillator
        .CLKHF(clk)
    );

    // 48 MHz / (2 * 12,000,000) = 2 Hz
    localparam int unsigned HALF_PERIOD = 12_000_000;

    logic [23:0] counter;

    always_ff @(posedge clk) begin
        if (counter == HALF_PERIOD - 1) begin
            counter <= '0;
            led     <= ~led;
        end
        else begin
            counter <= counter + 1'b1;
        end
    end

endmodule

